import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, color } from 'three/tsl';

function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const primitiveCleanups = [];
  let disposed = false;
  let loadedTexture = null;

  const visualSpec = config?.intent?.visualSpec ?? {};
  const palette = visualSpec.colors ?? {};
  const ink = palette.ink ?? '#16161d';
  const paper = palette.paper ?? '#e8ecf2';
  const accent = palette.accent ?? '#ff2a38';
  const surface = palette.surface ?? '#0b0b10';

  const geometry = new PlaneGeometry(2.4, 1.5, 1, 1);
  const backingGeometry = new PlaneGeometry(2.52, 1.62, 1, 1);
  const accentGeometry = new PlaneGeometry(0.06, 1.34, 1, 1);
  const edgeGeometry = new PlaneGeometry(2.34, 0.025, 1, 1);

  const backingMaterial = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.98,
    depthWrite: true
  });

  const imageMaterial = new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0.94,
    depthWrite: true
  });

  const gradientMaterial = new MeshBasicNodeMaterial({
    color: ink,
    transparent: true,
    opacity: 0.32,
    depthWrite: false
  });

  const accentMaterial = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0.96,
    depthWrite: true
  });

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0.42,
    depthWrite: false
  });

  const y = uv().y;
  const upperBlend = smoothstep(0.08, 0.9, y);
  const lowerBlend = smoothstep(0.55, 1.0, y);
  const darkGradient = mix(color(surface), color(ink), upperBlend);
  gradientMaterial.colorNode = mix(darkGradient, color(paper), lowerBlend.mul(0.1));

  const backing = new Mesh(backingGeometry, backingMaterial);
  backing.position.z = -0.035;

  const image = new Mesh(geometry, imageMaterial);
  image.position.z = 0;

  const gradient = new Mesh(geometry, gradientMaterial);
  gradient.position.z = 0.012;

  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.position.set(-1.12, 0, 0.035);

  const topEdge = new Mesh(edgeGeometry, edgeMaterial);
  topEdge.position.set(0, 0.78, 0.035);

  root.add(backing, image, gradient, accentBar, topEdge);

  const imageUrl = config?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture?.dispose?.();
        return;
      }

      loadedTexture = texture;
      if (texture && 'colorSpace' in texture && ctx.THREE.SRGBColorSpace) {
        texture.colorSpace = ctx.THREE.SRGBColorSpace;
      }
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  for (const primitive of config?.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const cleanup of primitiveCleanups) {
      try {
        cleanup();
      } catch {}
    }

    if (loadedTexture?.dispose) loadedTexture.dispose();

    for (const material of [
      backingMaterial,
      imageMaterial,
      gradientMaterial,
      accentMaterial,
      edgeMaterial
    ]) {
      material.dispose?.();
    }

    for (const resource of [
      geometry,
      backingGeometry,
      accentGeometry,
      edgeGeometry
    ]) {
      resource.dispose?.();
    }

    root.clear();
  };

  return root;
}

export default createNode;
